#import "CHMapController.h"
#import "CHProfileStore.h"
#import <WebKit/WebKit.h>
#import <CoreLocation/CoreLocation.h>

@interface CHMapController () <WKNavigationDelegate, WKScriptMessageHandler>
@property(nonatomic, strong) WKWebView *webView;
@property(nonatomic, assign) CLLocationCoordinate2D selectedCoordinate;
@property(nonatomic, copy) NSString *selectedPlaceLabel;
@property(nonatomic, assign) BOOL pageReady;
@end

@implementation CHMapController
- (void)viewDidLoad {
    [super viewDidLoad]; self.title = @"Choose Location"; self.view.backgroundColor = UIColor.systemBackgroundColor;
    WKWebViewConfiguration *configuration = [WKWebViewConfiguration new]; WKUserContentController *controller = [WKUserContentController new]; [controller addScriptMessageHandler:self name:@"location"]; configuration.userContentController = controller; configuration.websiteDataStore = WKWebsiteDataStore.defaultDataStore;
    self.webView = [[WKWebView alloc] initWithFrame:CGRectZero configuration:configuration]; self.webView.translatesAutoresizingMaskIntoConstraints = NO; self.webView.navigationDelegate = self; self.webView.backgroundColor = UIColor.systemBackgroundColor; [self.view addSubview:self.webView]; [NSLayoutConstraint activateConstraints:@[[self.webView.topAnchor constraintEqualToAnchor:self.view.topAnchor], [self.webView.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor], [self.webView.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor], [self.webView.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor]]];
    self.navigationItem.leftBarButtonItem = [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemCancel target:self action:@selector(close)]; self.navigationItem.rightBarButtonItem = [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemSave target:self action:@selector(saveLocation)];
    NSDictionary *location = self.store.profiles[self.profileIndex][@"location"]; double lat = [location[@"latitude"] doubleValue], lon = [location[@"longitude"] doubleValue]; if (lat < -90 || lat > 90 || lon < -180 || lon > 180 || (lat == 0 && lon == 0)) { lat = 34.016127; lon = -118.291403; } self.selectedCoordinate = CLLocationCoordinate2DMake(lat, lon); self.selectedPlaceLabel = location[@"label"] ?: @"Map selection"; [self.webView loadHTMLString:[self htmlForLatitude:lat longitude:lon label:self.selectedPlaceLabel] baseURL:[NSURL URLWithString:@"https://openstreetmap.org"]];
}
- (NSString *)htmlForLatitude:(double)lat longitude:(double)lon label:(NSString *)label {
    NSString *safeLabel = [label stringByReplacingOccurrencesOfString:@"\\" withString:@"\\\\"]; safeLabel = [safeLabel stringByReplacingOccurrencesOfString:@"\"" withString:@"\\\""];
    return [NSString stringWithFormat:@"<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1,maximum-scale=1'><link rel='stylesheet' href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'><style>html,body,#map{height:100%%;margin:0;background:#111;color:white;font-family:-apple-system}#search{position:absolute;z-index:1000;top:12px;left:12px;right:12px;display:flex;gap:6px}#query{flex:1;padding:12px;border:0;border-radius:12px;font-size:16px;background:#fff;color:#111;box-shadow:0 2px 8px #0006}button{border:0;border-radius:12px;padding:0 14px;background:#159f62;color:#fff;font-size:15px}#status{position:absolute;z-index:1000;left:12px;right:12px;bottom:16px;padding:10px 12px;border-radius:10px;background:#111d;color:#fff;text-align:center;font-size:13px}#results{position:absolute;z-index:1001;top:60px;left:12px;right:12px;background:#222;color:#fff;border-radius:10px;overflow:hidden;display:none}.result{padding:12px;border-bottom:1px solid #444;font-size:14px}</style></head><body><div id='search'><input id='query' placeholder='Search a street or city'><button onclick='findPlace()'>Find</button></div><div id='results'></div><div id='map'></div><div id='status'>Loading OpenStreetMap…</div><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script><script>const start=[%f,%f];let selected=start;let place="%@";let map,marker;function ready(){map=L.map('map').setView(start,13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);marker=L.marker(start,{draggable:true}).addTo(map);marker.on('dragend',()=>setPoint(marker.getLatLng().lat,marker.getLatLng().lng,'Map selection'));map.on('click',e=>setPoint(e.latlng.lat,e.latlng.lng,'Map selection'));document.getElementById('status').textContent='Tap the map or drag the pin';setPoint(start[0],start[1],place)}function setPoint(lat,lon,name){selected=[lat,lon];place=name||'Map selection';marker.setLatLng(selected);document.getElementById('status').textContent=place+'  ·  '+lat.toFixed(6)+', '+lon.toFixed(6);window.webkit.messageHandlers.location.postMessage({lat:lat,lon:lon,label:place})}async function findPlace(){let q=document.getElementById('query').value.trim();if(!q)return;document.getElementById('status').textContent='Searching…';try{let r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&q='+encodeURIComponent(q));let data=await r.json();let box=document.getElementById('results');box.innerHTML='';if(!data.length){document.getElementById('status').textContent='No matching location';box.style.display='none';return}data.forEach(item=>{let row=document.createElement('div');row.className='result';row.textContent=item.display_name;row.onclick=()=>{let lat=parseFloat(item.lat),lon=parseFloat(item.lon);map.setView([lat,lon],15);setPoint(lat,lon,item.display_name);box.style.display='none'};box.appendChild(row)});box.style.display='block';document.getElementById('status').textContent='Choose a result';}catch(e){document.getElementById('status').textContent='Search unavailable — check Wi‑Fi or try coordinates'}}window.addEventListener('load',()=>{if(window.L)ready();else document.getElementById('status').textContent='Map source unavailable — check Wi‑Fi'});</script></body></html>", lat, lon, safeLabel];
}
- (void)userContentController:(WKUserContentController *)userContentController didReceiveScriptMessage:(WKScriptMessage *)message { if (![message.body isKindOfClass:NSDictionary.class]) return; NSDictionary *d = message.body; self.selectedCoordinate = CLLocationCoordinate2DMake([d[@"lat"] doubleValue], [d[@"lon"] doubleValue]); self.selectedPlaceLabel = d[@"label"] ?: @"Map selection"; }
- (void)saveLocation { [self.store setLatitude:self.selectedCoordinate.latitude longitude:self.selectedCoordinate.longitude label:self.selectedPlaceLabel ?: @"Map selection" forProfileAtIndex:self.profileIndex]; [self close]; }
- (void)close { [self.webView.configuration.userContentController removeScriptMessageHandlerForName:@"location"]; [self dismissViewControllerAnimated:YES completion:nil]; }
- (void)dealloc { [self.webView.configuration.userContentController removeScriptMessageHandlerForName:@"location"]; }
@end
